import React, { useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from '../libs/toast';
import { useNavigate } from 'react-router-dom';
import DatePicker from 'react-multi-date-picker';
import persian from 'react-date-object/calendars/persian';
import persian_fa from 'react-date-object/locales/persian_fa';

const toPersianDigits = (str: string | number) => {
  const s = String(str);
  const d = ['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹'];
  return s.replace(/[0-9]/g, (w) => d[+w]);
};

const CreateEstimate: React.FC = () => {
  const [programs, setPrograms] = useState<any[]>([]);
  const [roles, setRoles] = useState<any[]>([]);

  const [form, setForm] = useState<any>({
    program_id: '',
    estimate_code: '',
    duration_minutes: '',
    program_count: '',
    minute_rate: '',
    expiration_date: '',
    linked_to_estimate_id: '',
    hospitality_cost: '',
    transport_cost: '',
    misc_cost: '',
    description: ''
  });

  const [roleWageDraft, setRoleWageDraft] = useState<any>({
    role_id: '',
    role_name: '',
    role_code: '',
    wage_amount: '',
    wage_percent: ''
  });

  const [createdEstimateId, setCreatedEstimateId] = useState<number | null>(null);
  const navigate = useNavigate();

  const token = localStorage.getItem('token');
  const authHeaders = token ? { Authorization: `Bearer ${token}` } : undefined;

  useEffect(() => { fetchPrograms(); fetchRoles(); }, []);

  const fetchPrograms = async () => {
    try { const res = await axios.get('/api/programs'); setPrograms(res.data); }
    catch { toast.error('خطا در دریافت برنامه‌ها'); }
  };

  const fetchRoles = async () => {
    try { const res = await axios.get('/api/roles'); setRoles(res.data); }
    catch { toast.error('خطا در دریافت نقش‌ها'); }
  };

  const onChange = (key: string, value: any) => setForm((f: any) => ({ ...f, [key]: value }));

  const submitEstimate = async () => {
    const required = ['program_id','estimate_code','duration_minutes','program_count','minute_rate'];
    for (const k of required) {
      if (!String(form[k] || '').trim()) { toast.error('فیلدهای اصلی را کامل کنید'); return; }
    }
    try {
      const payload = {
        program_id: Number(form.program_id),
        estimate_code: form.estimate_code.trim(),
        duration_minutes: Number(form.duration_minutes),
        program_count: Number(form.program_count),
        minute_rate: Number(form.minute_rate),
        expiration_date: form.expiration_date || null,
        linked_to_estimate_id: form.linked_to_estimate_id ? Number(form.linked_to_estimate_id) : null,
        hospitality_cost: form.hospitality_cost ? Number(form.hospitality_cost) : 0,
        transport_cost: form.transport_cost ? Number(form.transport_cost) : 0,
        misc_cost: form.misc_cost ? Number(form.misc_cost) : 0,
        description: form.description || ''
      };
      const res = await axios.post('/api/estimates', payload, { headers: authHeaders });
      setCreatedEstimateId(res.data.id);
      toast.success('برآورد ثبت شد، حالا دستمزد نقش‌ها را اضافه کنید');
    } catch {
      toast.error('ثبت برآورد با خطا مواجه شد');
    }
  };

  const addRoleWage = async () => {
    if (!createdEstimateId) { toast.error('ابتدا برآورد را ثبت کنید'); return; }
    const payload: any = {
      role_id: roleWageDraft.role_id ? Number(roleWageDraft.role_id) : null,
      role_code: roleWageDraft.role_code || null,
      role_name: roleWageDraft.role_name || null,
      wage_amount: roleWageDraft.wage_amount ? Number(roleWageDraft.wage_amount) : null,
      wage_percent: roleWageDraft.wage_percent ? Number(roleWageDraft.wage_percent) : null
    };
    if (!payload.role_id && !payload.role_code && !payload.role_name) {
      toast.error('حداقل یکی از نقش یا نام/کد نقش را وارد کنید');
      return;
    }
    try {
      await axios.post(`/api/estimates/${createdEstimateId}/roles`, payload, { headers: authHeaders });
      toast.success('دستمزد نقش اضافه شد');
      setRoleWageDraft({ role_id: '', role_name: '', role_code: '', wage_amount: '', wage_percent: '' });
    } catch {
      toast.error('ثبت دستمزد نقش با خطا مواجه شد');
    }
  };

  const totalMinutes = useMemo(() => {
    const d = Number(form.duration_minutes || 0); const c = Number(form.program_count || 0);
    return d * c;
  }, [form.duration_minutes, form.program_count]);

  const totalAmount = useMemo(() => {
    const r = Number(form.minute_rate || 0); return r * totalMinutes;
  }, [form.minute_rate, totalMinutes]);

  return (
    <div className="page-container">
      <div className="page-header">
        <h1>ثبت برآورد جدید</h1>
        <button className="btn" onClick={() => navigate('/estimates')}>بازگشت</button>
      </div>

      <div className="form-card">
        <div className="form-row">
          <label>برنامه</label>
          <select value={form.program_id} onChange={(e) => onChange('program_id', e.target.value)}>
            <option value="">انتخاب کنید</option>
            {programs.map((p) => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>

        <div className="form-row">
          <label>کد برآورد یکتا</label>
          <input value={form.estimate_code} onChange={(e) => onChange('estimate_code', e.target.value)} placeholder="مثلاً EST-1403-001" />
        </div>

        <div className="form-grid">
          <div className="form-row">
            <label>مدت هر برنامه (دقیقه)</label>
            <input type="number" value={form.duration_minutes} onChange={(e) => onChange('duration_minutes', e.target.value)} />
          </div>
          <div className="form-row">
            <label>تعداد برنامه</label>
            <input type="number" value={form.program_count} onChange={(e) => onChange('program_count', e.target.value)} />
          </div>
          <div className="form-row">
            <label>نرخ هر دقیقه (تومان)</label>
            <input type="number" value={form.minute_rate} onChange={(e) => onChange('minute_rate', e.target.value)} />
          </div>
        </div>

        <div className="hint-row">
          <span>دقیقه کل: {toPersianDigits(totalMinutes)}</span>
          <span>مبلغ کل: {toPersianDigits(totalAmount)}</span>
        </div>

        <div className="form-grid">
          <div className="form-row">
            <label>تاریخ انقضا (شمسی)</label>
            <DatePicker
              calendar={persian}
              locale={persian_fa}
              value={form.expiration_date ? new Date(form.expiration_date) : undefined}
              format="YYYY-MM-DD"
              onChange={(date: any) => {
                try {
                  const str = Array.isArray(date) ? '' : date?.format?.('YYYY-MM-DD') || '';
                  onChange('expiration_date', str);
                } catch {
                  onChange('expiration_date', '');
                }
              }}
              inputClass="date-input"
            />
          </div>
          <div className="form-row">
            <label>برآورد پیوست (اختیاری)</label>
            <input value={form.linked_to_estimate_id} onChange={(e) => onChange('linked_to_estimate_id', e.target.value)} placeholder="شناسه برآورد قبلی" />
          </div>
        </div>

        <div className="form-grid">
          <div className="form-row">
            <label>پذیرایی</label>
            <input type="number" value={form.hospitality_cost} onChange={(e) => onChange('hospitality_cost', e.target.value)} />
          </div>
          <div className="form-row">
            <label>ایاب و ذهاب</label>
            <input type="number" value={form.transport_cost} onChange={(e) => onChange('transport_cost', e.target.value)} />
          </div>
          <div className="form-row">
            <label>هزینه‌های متفرقه</label>
            <input type="number" value={form.misc_cost} onChange={(e) => onChange('misc_cost', e.target.value)} />
          </div>
        </div>

        <div className="form-row">
          <label>توضیحات</label>
          <textarea value={form.description} onChange={(e) => onChange('description', e.target.value)} />
        </div>

        <button className="btn btn-success" onClick={submitEstimate}>ثبت برآورد</button>
      </div>

      <div className="form-card">
        <h2>تعریف دستمزد نقش‌ها</h2>
        {!createdEstimateId && <p className="muted">برای اضافه کردن نقش‌ها، ابتدا برآورد را ثبت کنید.</p>}
        <div className="form-grid">
          <div className="form-row">
            <label>انتخاب از لیست نقش‌ها</label>
            <small className="muted">مرتب بر اساس رتبه (عدد کوچکتر یعنی جایگاه بالاتر)</small>
            <select value={roleWageDraft.role_id} onChange={(e) => setRoleWageDraft((d: any) => ({ ...d, role_id: e.target.value }))}>
              <option value="">—</option>
              {roles.map((r) => <option key={r.id} value={r.id}>{r.name} ({r.code} • رتبه {r.rank ?? 999})</option>)}
            </select>
          </div>
          <div className="form-row">
            <label>یا کد نقش</label>
            <input value={roleWageDraft.role_code} onChange={(e) => setRoleWageDraft((d: any) => ({ ...d, role_code: e.target.value }))} placeholder="مثلاً soundman" />
          </div>
          <div className="form-row">
            <label>نام نقش</label>
            <input value={roleWageDraft.role_name} onChange={(e) => setRoleWageDraft((d: any) => ({ ...d, role_name: e.target.value }))} placeholder="مثلاً صدابردار" />
          </div>
        </div>

        <div className="form-grid">
          <div className="form-row">
            <label>حق‌الزحمه عددی (تومان)</label>
            <input type="number" value={roleWageDraft.wage_amount} onChange={(e) => setRoleWageDraft((d: any) => ({ ...d, wage_amount: e.target.value }))} />
          </div>
          <div className="form-row">
            <label>حق‌الزحمه درصدی (%)</label>
            <input type="number" value={roleWageDraft.wage_percent} onChange={(e) => setRoleWageDraft((d: any) => ({ ...d, wage_percent: e.target.value }))} />
          </div>
        </div>

        <button className="btn" onClick={addRoleWage}>افزودن دستمزد نقش</button>
      </div>
    </div>
  );
};

export default CreateEstimate;
